
/* ATLAS 7.2 — DIRECT LIVE BROADCAST RENDERER */
function atlas72Arr(v){return Array.isArray(v)?v:(v&&typeof v==="object"?Object.values(v):[])}
function atlas72Team(g,side){return g?.[side]||g?.competitors?.find?.(x=>x.homeAway===side)||{}}
function atlas72Val(x,...ks){for(const k of ks){let v=x?.[k];if(v!==undefined&&v!==null&&v!=="")return v}return null}
function atlas72Broadcast(g){
  if(!g)return `<section class="broadcast72 empty72">SELECT A GAME TO OPEN LIVE COMMAND CENTER</section>`;
  const A=atlas72Team(g,"away"),H=atlas72Team(g,"home");
  const status=g.status||{}, sit=g.situation||g.drive?.situation||{};
  const plays=atlas72Arr(g.plays||g.recentPlays||g.recent_plays).slice(-8).reverse();
  const drives=atlas72Arr(g.drives||g.drive_history||g.driveHistory).slice(-8);
  const leaders=atlas72Arr(g.leaders||g.player_leaders);
  const scoring=plays.filter(p=>p.scoringPlay||p.scoring||/touchdown|field goal|safety/i.test(p.text||p.description||"")).reverse();
  const q=atlas72Val(status,"period")??atlas72Val(g,"period");
  const clock=atlas72Val(status,"displayClock","clock")??atlas72Val(g,"clock");
  const detail=atlas72Val(status,"shortDetail","detail","description")??atlas72Val(g,"status_text","statusText");
  const state=String(atlas72Val(status,"state")??atlas72Val(g,"state")??"").toLowerCase();
  const live=state==="in"||state==="live"||/quarter|q[1-4]|halftime/i.test(String(detail||""));
  const score=x=>atlas72Val(x,"score","points")??atlas72Val(x?.team,"score","points")??"—";
  const ab=x=>atlas72Val(x,"abbr","abbreviation")??atlas72Val(x?.team,"abbreviation","abbr")??"—";
  const logo=x=>atlas72Val(x,"logo")??atlas72Val(x?.team,"logo")??"";
  const down=atlas72Val(sit,"downDistanceText","shortDownDistanceText")??atlas72Val(g,"downDistance","down_distance");
  const poss=atlas72Val(sit,"possessionText")??atlas72Val(g,"possession");
  const yard=Number(atlas72Val(sit,"yardLine","yard_line","absoluteYardline")??atlas72Val(g,"yardLine","yard_line"));
  const pct=Number.isFinite(yard)?Math.max(3,Math.min(97,yard)):50;
  const leaderHTML=leaders.slice(0,6).map(x=>{const a=x.athlete||x.player||x;return `<div class="impact72"><img src="${a.headshot?.href||a.headshot||""}"><span><b>${a.displayName||a.name||x.name||"Player"}</b><small>${x.displayValue||x.value||x.stat||x.category||""}</small></span></div>`}).join("");
  return `<section class="broadcast72">
   <div class="broadcast72bar"><b>${live?"● LIVE GAME COMMAND":"GAME COMMAND"}</b><span>${detail||"Verified game feed"}</span><i>ATLAS 7.2</i></div>
   <div class="score72">
    <div class="side72"><img src="${logo(A)}"><span><b>${ab(A)}</b><small>AWAY</small></span><strong>${score(A)}</strong></div>
    <div class="center72"><b>${q?`Q${q}`:""} ${clock||""}</b><span>${down||""}</span><span>${poss||""}</span></div>
    <div class="side72 home72"><strong>${score(H)}</strong><span><b>${ab(H)}</b><small>HOME</small></span><img src="${logo(H)}"></div>
   </div>
   <div class="field72"><div class="zones72"></div><div class="first72" style="left:${Math.min(94,pct+10)}%"></div><div class="ball72" style="left:${pct}%">◆</div><div class="fieldtext72"><b>${down||"FIELD POSITION"}</b><span>${poss||"Verified situation updates with the game feed"}</span></div></div>
   <div class="dash72">
    <article><h3>WHAT JUST HAPPENED</h3><div class="plays72">${plays.length?plays.map((p,i)=>`<div class="${i===0?"hot72":""}"><b>${p.clock?.displayValue||p.clock||p.displayClock||""}</b><span>${p.text||p.description||p.play_text||"Verified play"}</span></div>`).join(""):`<p class="wait72">Waiting for verified play-by-play.</p>`}</div></article>
    <article><h3>DRIVE CENTER</h3><div class="drives72">${drives.length?drives.map(d=>`<div><b>${d.team?.abbreviation||d.team||"DRIVE"}</b><span>${d.description||d.result||d.displayResult||"Verified drive"}</span><small>${d.plays??""}${d.plays?" plays":""} ${d.yards??""}${d.yards?" yds":""}</small></div>`).join(""):`<p class="wait72">Drive history appears when supplied by the verified feed.</p>`}</div></article>
    <article><h3>IMPACT PLAYERS</h3><div class="impactgrid72">${leaderHTML||`<p class="wait72">Verified player leaders are building.</p>`}</div></article>
    <article><h3>SCORING TIMELINE</h3><div class="scoring72">${scoring.length?scoring.map(p=>`<div><b>${p.period?.number?`Q${p.period.number}`:""} ${p.clock?.displayValue||p.clock||""}</b><span>${p.text||p.description||"Scoring play"}</span></div>`).join(""):`<p class="wait72">No verified scoring events in the current play window.</p>`}</div></article>
   </div>
   <div class="story72"><h3>GAME STORY</h3><p>${plays[0]?.text||plays[0]?.description||detail||"ATLAS is waiting for verified game events."}</p><button class="ask61" data-atlas-prompt="Explain this NFL game right now using only verified ATLAS game evidence.">✦ ASK ATLAS</button></div>
  </section>`;
}


function mountNFLGameCast61(g){
 let root=document.querySelector("main")||document.querySelector("#app");if(!root||!g)return;
 let existing=document.getElementById("nflGameCast61");if(existing)existing.remove();
 let host=document.createElement("section");host.id="nflGameCast61";host.innerHTML=nflBroadcast60(g);
 let target=root.querySelector(".grid,.cards,.content")||root;target.prepend(host);
 ATLAS60.attach(host)
}

function nflBroadcast60(g){let p=Number(g?.situation?.yardLine??g?.field_position??50),ev=(g?.plays||g?.recent_plays||[]).map(x=>({period:x.period||x.quarter||"",text:x.text||x.description||x.playText||""})).filter(x=>x.text);return `<section class="card full"><h3>GAMECAST 2.0</h3>${ATLAS60.field(p)}${ATLAS60.eventTimeline(ev)}</section>`}

function nflMomentum53(g){let plays=g?.plays||g?.recent_plays||[];let vals=[];for(let p of plays){let y=Number(p?.yards??p?.yards_gained??p?.statYardage);if(Number.isFinite(y))vals.push(y)}return ATLAS53.spark(vals.slice(-20),{label:"RECENT PLAY YARDAGE FLOW",suffix:" YDS"})}
function nflScorePulse53(g){let a=Number(g?.away?.score??g?.away_score),h=Number(g?.home?.score??g?.home_score);if(!Number.isFinite(a)||!Number.isFinite(h))return '<div class="empty">Score pulse waits for verified score data.</div>';return `<div class="scorepulse53"><div><span>${g?.away?.abbr||g?.away?.team||"AWAY"}</span><b>${a}</b></div><i></i><div><span>${g?.home?.abbr||g?.home?.team||"HOME"}</span><b>${h}</b></div></div>`}


function atlasLineChart(rows,xKey,yKey,label){
 rows=(rows||[]).map(r=>({x:r?.[xKey],y:Number(r?.[yKey])})).filter(r=>r.x!=null&&Number.isFinite(r.y)&&r.y!==null);
 if(rows.length<2)return `<div class="empty">More verified data is needed for this trend.</div>`;
 let W=760,H=230,P=28,ys=rows.map(r=>r.y),mn=Math.min(...ys),mx=Math.max(...ys);if(mx===mn){mx+=1;mn-=1}
 let X=i=>P+i*(W-P*2)/Math.max(1,rows.length-1),Y=v=>H-P-(v-mn)*(H-P*2)/(mx-mn);
 let pts=rows.map((r,i)=>`${X(i)},${Y(r.y)}`).join(" "),area=`${P},${H-P} ${pts} ${W-P},${H-P}`;
 let grid=[0,.25,.5,.75,1].map(t=>`<line class="gridline" x1="${P}" x2="${W-P}" y1="${P+t*(H-P*2)}" y2="${P+t*(H-P*2)}"/>`).join("");
 let dots=rows.map((r,i)=>`<circle class="dot" cx="${X(i)}" cy="${Y(r.y)}" r="4"><title>${String(r.x)} · ${r.y}</title></circle>`).join("");
 return `<div class="chart-title"><b>${label}</b><span>${rows.length} VERIFIED POINTS</span></div><svg class="atlas-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${label}">${grid}<polygon class="area" points="${area}"/><polyline class="line" points="${pts}"/>${dots}<text class="axis" x="${P}" y="${H-5}">${String(rows[0].x)}</text><text class="axis" text-anchor="end" x="${W-P}" y="${H-5}">${String(rows[rows.length-1].x)}</text></svg>`}

