const cache=new Map();
const A=v=>Array.isArray(v)?v:(v&&Array.isArray(v.items)?v.items:v&&Array.isArray(v.rows)?v.rows:v&&Array.isArray(v.stats)?v.stats:[]);
const O=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
const N=v=>{const n=parseFloat(String(v??'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:0};
