function dataState(title,detail,action='',route=''){return `<div class="data-state759"><div class="state-orb759">A</div><div><b>${E(title)}</b><p>${E(detail)}</p></div>${action?`<button ${route?`data-jump="${E(route)}"`:''}>${E(action)}</button>`:''}</div>`}

