function dualBars72(rows,a='FOR',b='AGAINST'){rows=A(rows).slice(-10);const mx=Math.max(1,...rows.flatMap(x=>[Math.abs(N(x.a)),Math.abs(N(x.b))]));return `<div class="dual72"><div class="legend72"><span><i></i>${E(a)}</span><span><i></i>${E(b)}</span></div>${rows.map(x=>`<div><label>${E(x.k)}</label><i><em style="width:${Math.max(2,Math.abs(N(x.a))/mx*100)}%"></em></i><b>${E(x.a)}</b><i class="alt"><em style="width:${Math.max(2,Math.abs(N(x.b))/mx*100)}%"></em></i><b>${E(x.b)}</b></div>`).join('')||dataState('Comparison building','This visual needs verified values from multiple games.')}</div>`}
function donut72(rows){rows=A(rows).filter(x=>N(x.v)>0);let total=rows.reduce((s,x)=>s+N(x.v),0);if(!total)return dataState('Distribution building','This chart activates when verified values are available.');let acc=0,cols=['#ff9d68','#ff7b63','#d65a8b','#d65a8b','#ff9d42','#ffb15c'];let stops=rows.map((x,i)=>{let a=acc/total*100;acc+=N(x.v);return `${cols[i%cols.length]} ${a}% ${acc/total*100}%`}).join(',');return `<div class="donut72"><i style="background:conic-gradient(${stops})"><b>${E(total)}</b><small>TOTAL</small></i><div>${rows.map((x,i)=>`<p><em style="background:${cols[i%cols.length]}"></em><span>${E(x.k)}</span><b>${E(x.v)}</b></p>`).join('')}</div></div>`}
function scatter72(rows,xLabel='STRENGTH',yLabel='PROJECTED WINS'){rows=A(rows).filter(x=>Number.isFinite(N(x.x))&&Number.isFinite(N(x.y)));if(rows.length<2)return '<p class="empty chart-empty">More model points are needed.</p>';let xs=rows.map(x=>N(x.x)),ys=rows.map(x=>N(x.y)),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xd=xmax-xmin||1,yd=ymax-ymin||1;return `<div class="scatter72"><svg viewBox="0 0 100 100">${rows.map(x=>`<g><circle cx="${8+(N(x.x)-xmin)/xd*84}" cy="${90-(N(x.y)-ymin)/yd*80}" r="2.2"></circle><text x="${8+(N(x.x)-xmin)/xd*84}" y="${86-(N(x.y)-ymin)/yd*80}">${E(x.k)}</text></g>`).join('')}</svg><footer><span>${E(xLabel)} →</span><span>↑ ${E(yLabel)}</span></footer></div>`}
