function impact74(x){let s=O(x.stats),pos=String(x.position||'').toUpperCase(),get=(keys)=>{for(let [k,v] of Object.entries(s)){let z=k.toLowerCase().replace(/[^a-z]/g,'');if(keys.some(q=>z.includes(q)))return N(v)}return 0};let score=0,why=[];if(pos==='QB'){let y=get(['yds','yards']),td=get(['td']),ints=get(['int']);score=y/25+td*4-ints*2;why=[`${y} pass yds`,`${td} TD`,`${ints} INT`]}else if(['RB','WR','TE','FB'].includes(pos)){let y=get(['yds','yards']),td=get(['td']),rec=get(['rec']);score=y/10+td*6+rec;why=[`${y} yds`,`${td} TD`,`${rec} rec`]}else{score=Object.values(s).map(N).reduce((a,v)=>a+Math.abs(v),0);why=Object.entries(s).slice(0,3).map(([k,v])=>`${k} ${v}`)}return {score:Math.round(score*10)/10,why}}
